node --input-type=module <<'JS'
import { readFileSync, writeFileSync } from 'node:fs';
const files = [
  '.github/workflows/ci.yml',
  'package.json',
  'mise.toml',
  'vite.bench.config.ts',
  'bench/core.bench.ts',
  'bench/formats.bench.ts',
  'tools/validate-generated/index.ts',
  'tools/validate-generated/README.md',
  'renderers/web-components/tests/i18n-node-free.test.ts',
  'scripts/quality/accessibility-workflow.test.ts',
  'CONTRIBUTING.md',
];
const oldText = 'vp run -r build';
const newText = 'vp run -r --concurrency-limit 1 build';
for (const file of files) {
  const text = readFileSync(file, 'utf8');
  const count = text.split(oldText).length - 1;
  if (count > 0) writeFileSync(file, text.replaceAll(oldText, newText));
  console.log(`${file}: updated ${count}`);
}
