  // into several packages' internals at once (deliberately, to time them individually), which makes
  // fallow report cross-package name collisions that don't exist for real consumers — no published
  // barrel exposes `formats/scss`'s and `formats/dtcg`'s `Mode` together. `vitest bench` discovers the
  // files, so nothing here needs to be reachable from the module graph.
  "ignorePatterns": [
    ".i18n/**",
    ".worktrees/**",
    "coverage/**",
    "bench/**",
    // VitePress dev pre-bundles dependencies here. The folder is gitignored cache output, not source.
    "docs/.vitepress/cache/**",
    "docs/docs/.vitepress/cache/**",
    // Locale docs are generated translated mirrors rather than source modules in the package graph.
    "docs/{ar,ca,cy,da,de,el,en-AU,en-CA,en-GB,es,fa,fi,fr,fr-CA,ga,he,hi,ht,hu,hy,id,is,it,ja,ko,mi,ms,nb,nl,nn,pl,pt,pt-BR,ru,se,sl,sv,th,tr,uk,vi,zh-Hans,zh-Hant}/**",
    "ai/create-pantoken-app-site",
    "plugins/pantoken",
    "plugins/pantoken/scripts",
    // These Less sources are compiled from seven entry points by renderers/tinymce/scripts/generate.ts.
    // Fallow cannot resolve their Less imports, so it reports their build-only files as unused and
    // their intentional theme variants as duplicates.
    "renderers/tinymce/oxide/**"
